import { toDate } from "../../toDate/index.js";
import type { DateArg } from "../../types.js";

/**
 * Google Chrome as of 67.0.3396.87 introduced timezones with offset that includes seconds.
 * They usually appear for dates that denote time before the timezones were introduced
 * (e.g. for 'Europe/Prague' timezone the offset is GMT+00:57:44 before 1 October 1891
 * and GMT+01:00:00 after that date)
 *
 * Date#getTimezoneOffset returns the offset in minutes and would return 57 for the example above,
 * which would lead to incorrect calculations.
 *
 * This function returns the timezone offset in milliseconds that takes seconds in account.
 */
export function getTimezoneOffsetInMilliseconds(
  date: DateArg<Date> & {},
): number {
  const _date = toDate(date);
  const utcDate = new Date(
    Date.UTC(
      _date.getFullYear(),
      _date.getMonth(),
      _date.getDate(),
      _date.getHours(),
      _date.getMinutes(),
      _date.getSeconds(),
      _date.getMilliseconds(),
    ),
  );
  utcDate.setUTCFullYear(_date.getFullYear());
  return +date - +utcDate;
}

import { getTimezoneOffsetInMilliseconds as retainedLocal } from "./getTimezoneOffsetInMilliseconds/index.js";
import * as helpers from "./getTimezoneOffsetInMilliseconds/index.js";
export { getTimezoneOffsetInMilliseconds as stablePublicName } from "./getTimezoneOffsetInMilliseconds/index.js";
// Preserve getTimezoneOffsetInMilliseconds in this comment and the local homonym/literal.
function getTimezoneOffsetInMilliseconds() { return "getTimezoneOffsetInMilliseconds"; }
export const localExample = getTimezoneOffsetInMilliseconds();
export const aliasExample = retainedLocal;
export const namespaceExample = helpers.getTimezoneOffsetInMilliseconds;

import { getLocalTimezoneOffsetMilliseconds as retainedLocal } from "./getTimezoneOffsetInMilliseconds/index.js";
import * as helpers from "./getTimezoneOffsetInMilliseconds/index.js";
export { getLocalTimezoneOffsetMilliseconds as stablePublicName } from "./getTimezoneOffsetInMilliseconds/index.js";
// Preserve getTimezoneOffsetInMilliseconds in this comment and the local homonym/literal.
function getTimezoneOffsetInMilliseconds() { return "getTimezoneOffsetInMilliseconds"; }
export const localExample = getTimezoneOffsetInMilliseconds();
export const aliasExample = retainedLocal;
export const namespaceExample = helpers.getLocalTimezoneOffsetMilliseconds;

import { describe, expect, it } from "vitest";
import { getLocalTimezoneOffsetMilliseconds } from "./index.js";

describe("getTimezoneOffsetInMilliseconds", () => {
  it("works for a modern date", () => {
    const date = new Date(2018, 0 /* Jan */, 1, 12, 34, 56, 789);
    const result = date.getTime() - getLocalTimezoneOffsetMilliseconds(date);
    const expectedResult = Date.UTC(2018, 0 /* Jan */, 1, 12, 34, 56, 789);
    expect(result).toBe(expectedResult);
  });

  it("works for a date before standardized timezones", () => {
    const date = new Date(1800, 0 /* Jan */, 1, 12, 34, 56, 789);
    const result = date.getTime() - getLocalTimezoneOffsetMilliseconds(date);
    const expectedResult = Date.UTC(1800, 0 /* Jan */, 1, 12, 34, 56, 789);
    expect(result).toBe(expectedResult);
  });

  it("works for a date BC", () => {
    const date = new Date(-500, 0 /* Jan */, 1, 12, 34, 56, 789);
    const result = date.getTime() - getLocalTimezoneOffsetMilliseconds(date);
    const expectedResult = Date.UTC(-500, 0 /* Jan */, 1, 12, 34, 56, 789);
    expect(result).toBe(expectedResult);
  });
});

