      next: (value) => {
        if (settled) {
          return;
        }
        _value = value;
        _hasValue = true;
      },
      error: (err) => {
        if (settled) {
          return;
        }
        settled = true;
        signal?.removeEventListener('abort', abortHandler);
        reject(err);
      },
